#include <vector>
#include <iostream>
using namespace std;
class Solution {
public:
    int totalHammingDistance(vector<int>& nums) { //with the help of the solutions
        int n = nums.size();
        if(n == 0) return 0;
        int sum = 0;
        for(int j = 0 ; j < 32 ; j++){
        int ones = 0 , zeros = 0;
          for(int i = 0 ; i < n ; i++){
             if(nums[i]&1 == 1)ones++;
             else zeros++;
             nums[i] >>= 1;
            }
            sum += zeros*ones;
        }
        
        return sum;
    }
};

